const BY_CONNECTION_TYPE = new Map<number, DatabaseTypeDescriptor>(
  DATABASE_TYPES.map((item) => [item.connectionType, item]),
);

export const descriptorByConnectionType = (
  connectionType: number,
): DatabaseTypeDescriptor | undefined => BY_CONNECTION_TYPE.get(connectionType);

export const supportsCapability = (
  connectionType: number,
  capability: Capability,
): boolean =>
  descriptorByConnectionType(connectionType)?.capabilities.includes(capability) ??
  false;
